#[path="../triangular-witness/core.rs"]mod core;
#[path="../triangular-witness/cost.rs"]mod cost;
#[path="../canonical-root/root.rs"]mod root;
use hec_native_ic::{counted,fp::Fp,poly::Poly,jac::Curve,instance::factor_base,rng::Rng};
fn witness(rows:&[Vec<u64>],want:&[u64],f:&Fp)->Option<Vec<u64>>{let n=want.len();let mut basis:Vec<Option<(Vec<u64>,Vec<u64>)>>=vec![None;n];for(i,row)in rows.iter().enumerate(){let mut a=row.clone();let mut w=vec![0;rows.len()];w[i]=1;for j in 0..n{if a[j]==0{continue}if let Some((p,q))=&basis[j]{let t=a[j];for k in j..n{a[k]=f.sub(a[k],f.mul(t,p[k]));}for k in 0..w.len(){w[k]=f.sub(w[k],f.mul(t,q[k]));}}else{let inv=f.inv(a[j]);for x in &mut a{*x=f.mul(*x,inv);}for x in &mut w{*x=f.mul(*x,inv);}basis[j]=Some((a,w));break}}}let mut rem=want.to_vec();let mut out=vec![0;rows.len()];for j in 0..n{if rem[j]==0{continue}let(p,q)=basis[j].as_ref()?;let t=rem[j];for k in j..n{rem[k]=f.sub(rem[k],f.mul(t,p[k]));}for k in 0..out.len(){out[k]=f.add(out[k],f.mul(t,q[k]));}}if rem.iter().all(|x|*x==0){Some(out)}else{None}}
fn verify(rows:&[Vec<u64>],want:&[u64],w:&[u64],f:&Fp)->bool{if w.len()!=rows.len(){return false}let mut out=vec![0;want.len()];for(row,&a)in rows.iter().zip(w){for j in 0..out.len(){out[j]=f.add(out[j],f.mul(a,row[j]));}}out==want}
fn synthetic(){for(n,ell)in[(5,11),(7,29),(9,19)]{let f=Fp::new(ell);let z=root::power_map(&f,n).0;let roots:Vec<_>=(1..n).map(|i|f.pow(z,i)).collect();let mut product=Poly::one();for &r in &roots{product=product.mul(&Poly::x_minus(r,&f),&f);}assert_eq!(product,Poly::from_coeffs(&vec![1;n as usize]));let m=2*ell;let e=2*f.inv(2);assert_eq!((e*e)%m,e%m);assert_eq!((ell*e)%m,0);assert_eq!(e%ell,1);let rd=z;let rt=if n==9{f.pow(z,3)}else{f.pow(z,2)};assert_ne!(rd,rt);let d=[1,0];let t=[0,1];let k=0;let mut old_cover_accepts=true;let mut homogeneous_accepts=true;for &r in &roots{let dr=if r==rd{d}else{[0,0]};let tr=if r==rt{t}else{[0,0]};let excluded=dr==[0,0];let scalar=tr==dr.map(|x|f.mul(k,x));old_cover_accepts&=excluded||scalar;homogeneous_accepts&=scalar;}assert!(old_cover_accepts);assert!(!homogeneous_accepts);assert_ne!(t,d.map(|x|f.mul(k,x)));if n==9{assert_eq!(f.pow(rt,3),1);assert_ne!(rt,1);}println!("MODULE\tn={n}\tell={ell}\th=2\tprojection={e}\tconditional_exclusion_unsafe_without_cyclic_premise=true\thomogeneous_cover_rejects=true");}}
fn main(){counted::disable();synthetic();let(mut cells,mut proved,mut unresolved,mut mutations)=(0,0,0,0);for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let fb=factor_base(&c);let pt=fb[0];let base=c.place(pt.0,pt.1);let mut rng=Rng::new(2026113000^p);for sm in[1,17]{let d=c.mul(&base,sm);for case in 0..2{let k=1+rng.below(ell-1);let target=c.mul(&d,k);let mut tr=None;for seed in 1..=3{let q=core::solve(&c,pt,&d,&target,ell,sm,seed,true,true);if q.answer.is_some(){tr=Some(q);break}}let tr=tr.unwrap();assert_eq!(tr.answer.unwrap().1,k);let f=Fp::new(ell);let z=root::power_map(&f,5).0;for exponent in 1..5{let r=f.pow(z,exponent);let n=tr.points.len()+2;let mut public=vec![0;n];public[0]=1;public[n-1]=f.neg(f.inv(sm));let mut rows=vec![public];let mut index=std::collections::BTreeMap::new();for(j,&(x,y))in tr.points.iter().enumerate(){let(mut xx,mut w)=(x,1);for _ in 0..5{assert!(index.insert((xx,y),(j,w)).is_none());let ny=c.fp.neg(y);if ny!=y{assert!(index.insert((xx,ny),(j,f.neg(w))).is_none());}xx=c.fp.mul(xx,tr.z);w=f.mul(w,r);}}for prim in &tr.primitives{let mut v=vec![0;n];v[n-2]=1;v[n-1]=prim.a;for xy in &prim.points{let &(j,w)=index.get(xy).unwrap();v[j]=f.add(v[j],w);}rows.push(v);}let mut want=vec![0;n];want[n-2]=1;want[n-1]=f.neg(tr.answer.unwrap().1);if let Some(w)=witness(&rows,&want,&f){assert!(verify(&rows,&want,&w,&f));let mut bad=w.clone();bad[0]=f.add(bad[0],1);assert!(!verify(&rows,&want,&bad,&f));mutations+=1;proved+=1;println!("PROOF\tp={p}\tsm={sm}\tcase={case}\tr={r}\tw={w:?}");}else{unresolved+=1;println!("UNRESOLVED\tp={p}\tsm={sm}\tcase={case}\tr={r}");}}cells+=1;}}}assert_eq!(cells,12);assert_eq!(proved+unresolved,48);eprintln!("PASS original_cells={cells} homogeneous_branch_proofs={proved} unresolved_branches={unresolved} weight_mutations_rejected={mutations} higher_rank_scope_counterexamples=3 no_cost_or_genus3_4_curve_claim=true independent_verification=false");}
